use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet}};
mod model;
const R:&str="/home/ubuntu/src/zopro-perf-work/parallel-readiness176";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert_eq!(read(r("native-final/result.json"))["status"],"complete");let mut pin_count=0;for(p,h)in read(r("final-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin_count+=1;}
 let mut commands=0;for(dir,names)in[("native",vec!["observer-tests","libraries-off","freeze-off"]),("native-rest",vec!["complete-link-metadata"]),("native-final",vec!["model-tests","model-tests-run","census-1x2","census-2x2"])]{for name in names{let base=r(format!("{dir}/{name}"));let exit=read(base.join("exit.json"));assert_eq!(exit["success"],true);assert_eq!(hash(base.join("stdout.log")),exit["stdout_sha256"]);assert_eq!(hash(base.join("stderr.log")),exit["stderr_sha256"]);commands+=1;}}
 assert_eq!(read(r("native/observer-tests/tests.json"))["passed_tests"].as_array().unwrap().len(),3);assert_eq!(read(r("native-final/model-tests-run/tests.json"))["passed_tests"].as_array().unwrap().len(),3);for p in["native/link-off/exit.json","native-rest/model-tests/exit.json"]{assert_eq!(read(r(p))["success"],false);}
 let inputs=read(r("inputs.json"));let mut cases=BTreeMap::new();let mut dependencies=0usize;let mut rows=0;
 for shape in["1x2","2x2"]{let a=read(r(format!("{shape}.json")));assert_eq!(a["complete"],true);assert_eq!(a["parallel"],true);for key in["image","solver"]{let p=inputs[shape][key].as_str().unwrap();assert_eq!(hash(p),inputs[shape][format!("{key}_sha256")]);assert_eq!(hash(p),a[format!("{key}_sha256")]);}
 let (meta,producer,edges,queries)=model::program(&fs::read(inputs[shape]["solver"].as_str().unwrap()).unwrap()).unwrap();assert_eq!(meta,a["serial_source_metadata"]);assert_eq!(meta,inputs[shape]["old_serialized_census"]);let bytes=fs::read(r(format!("{shape}.schedule.bin"))).unwrap();assert_eq!(format!("{:x}",Sha256::digest(&bytes)),a["raw_schedule_sha256"]);let words=bytes.chunks_exact(8).map(|b|u64::from_le_bytes(b.try_into().unwrap())).collect::<Vec<_>>();assert_eq!(bytes.len(),words.len()*8);let ops=words[1]as usize;let epochs=words[8]as usize;assert_eq!(words.len(),15+ops*5);let stamps=words[15..].chunks_exact(5).map(|a|<[u64;5]>::try_from(a).unwrap()).collect::<Vec<_>>();let mut locations=BTreeSet::new();for s in&stamps{assert!((s[0]as usize)<epochs);assert!(locations.insert(*s));}
 let mut last_read=vec![0usize;producer.len()];for &(wire,reader)in&edges{let writer=producer[wire];let b=stamps[reader-1];last_read[wire]=last_read[wire].max(b[0]as usize+1);if writer==0{continue;}if writer==reader{assert!(wire>=words[2]as usize);continue;}let a=stamps[writer-1];assert!(a[0]<b[0]||a[0]==b[0]&&a[1]==b[1]&&(a[2]<b[2]||a[2]==b[2]&&a[3]==b[3]&&a[4]<b[4]));dependencies+=1;}
 let mut epoch_details=Vec::new();for epoch in 0..epochs{let mut root=BTreeSet::new();let mut leaf=BTreeMap::<u64,usize>::new();let mut wave=BTreeSet::new();let mut total=0;for s in stamps.iter().filter(|s|s[0]==epoch as u64){root.insert(s[1]);*leaf.entry(s[3]).or_default()+=1;wave.insert((s[1],s[2]));total+=1;}epoch_details.push(json!({"epoch":epoch,"ops":total,"root_tasks":root.len(),"leaf_tasks":leaf.len(),"local_wave_groups":wave.len(),"max_leaf_ops":leaf.values().max().copied().unwrap_or(0)}));}
 let mut prerequisite=true;for(q,name)in["A","B"].iter().enumerate(){let ready_at=queries[q].iter().map(|&w|if producer[w]==0{0}else{stamps[producer[w]-1][0]as usize+1}).collect::<Vec<_>>();let mut histogram=vec![0usize;epochs+1];for &e in&ready_at{histogram[e]+=1;}let chunks=ready_at.chunks(1024).map(|v|(*v.iter().max().unwrap(),v.len())).collect::<Vec<_>>();let mut prefix=0;let mut ready=0;for cut in 0..=epochs{ready+=histogram[cut];while prefix<ready_at.len()&&ready_at[prefix]<=cut{prefix+=1;}let row=&a["query_results"][*name]["epoch_barriers"][cut];assert_eq!(row["epochs_completed"],cut);assert_eq!(row["ops_completed"],epoch_details[..cut].iter().map(|r|r["ops"].as_u64().unwrap()).sum::<u64>());assert_eq!(row["arbitrary_order_ready_points"],ready);assert_eq!(row["key_order_prefix_points"],prefix);assert_eq!(row["complete_1024_chunks"],chunks.iter().filter(|&&(e,_)|e<=cut).count());assert_eq!(row["points_in_complete_chunks"],chunks.iter().filter(|&&(e,_)|e<=cut).map(|&(_,n)|n).sum::<usize>());assert_eq!(row["past_final_solver_read_points"],queries[q].iter().enumerate().filter(|&(i,&w)|ready_at[i]<=cut&&last_read[w]<=cut).count());rows+=1;}
 assert_eq!(a["query_results"][*name]["initial_input_ready_points"],histogram[0]);assert_eq!(a["query_results"][*name]["points"],queries[q].len());let before=a["query_results"][*name]["epoch_barriers"][epochs-1]["key_order_prefix_points"].as_u64().unwrap();let initial=a["query_results"][*name]["epoch_barriers"][0]["key_order_prefix_points"].as_u64().unwrap();prerequisite&=before>initial;}
 assert_eq!(a["ordered_barrier_stream_structural_prerequisite"],prerequisite);cases.insert(shape,json!({"census":a,"epoch_task_geometry":epoch_details,"independent_query_epoch_rows":2*(epochs+1)}));}
 let manifest=read(format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new(Z).join(p)),h.as_str().unwrap());}let review=json!({"passed":true,"source_pins_checked":pin_count,"successful_commands":commands,"known_failed_helper_commands":2,"observer_tests":3,"reader_tests":3,"query_epoch_rows_recomputed":rows,"external_dependencies_checked":dependencies,"production176_exact":true,"new_solves":0,"new_proofs":0,"new_timings":0,"ledger":29255});fs::write(r("review.json"),serde_json::to_vec_pretty(&review).unwrap()).unwrap();let out=json!({"complete":true,"cases":cases,"review":review,"structural_opportunity_only":true,"adopted":false,"production_changed":false,"goal_achieved":false,"goal_status":"active","m5_inherited":manifest["m5"],"latest_full_SDK_measurement":"/home/ubuntu/src/zopro-perf-work/ifma-logjumps176/analysis.json"});fs::write(r("analysis.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{review}");for(shape,c)in out["cases"].as_object().unwrap(){println!("{shape} epochs={} taskcounts={:?}",c["census"]["epochs"],c["epoch_task_geometry"].as_array().unwrap().iter().map(|r|r["root_tasks"].as_u64().unwrap()).collect::<Vec<_>>());}}
